contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 loanID_, address to_) public {
        require(loanID_ != 0, "loanID must be nonzero to hit revert");

        uint256 approvalsBefore = uint256(uint160(c.approvals(loanID_)));
        require(approvalsBefore == 0, "stranger cannot be current approval");

        bool approveReverted;
        c.approveTransfer(to_, loanID_); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            approveReverted = true;
        } else {
            approveReverted = false;
        }
        assert(approveReverted);
    }

    receive() external payable {}
}

